func poll(workerId: String, capabilities: [String: Bool]) async throws -> (job: WorkerJob?, nextPollSeconds: Int?) {
    let (job, _, next) = try await pollRaw(workerId: workerId, capabilities: capabilities)
    return (job, next)
}

/// Same as `poll(workerId:capabilities:)` but also returns the raw
/// response body so callers can decode a `AutomationJob` (Automation runs ship
/// a different envelope — `payload: { automation, event, context }` and
/// no `connector_key`). Used by `SyncDispatcher` to branch on
/// `run_type` BEFORE the connector switch.
func pollRaw(workerId: String, capabilities: [String: Bool]) async throws -> (job: WorkerJob?, raw: Data?, nextPollSeconds: Int?) {
    struct Body: Encodable {
        let worker_id: String
        let capabilities: [String: Bool]
        let platform: String
        let app_version: String
        let label: String
        let connector_manifests: [[String: AnyEncodable]]
    }
    let appVersion = Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? "unknown"
    let label = Host.current().localizedName ?? "This Mac"
    let data = try await post(
        "/api/workers/poll",
        body: Body(
            worker_id: workerId,
            capabilities: capabilities,
            platform: "macos",
            app_version: appVersion,
            label: label,
            connector_manifests: DeviceConnectorManifests.load()
        )
    )
    struct Empty: Decodable { let next_poll_seconds: Int? }
    if let job = try? decoder.decode(WorkerJob.self, from: data) {
        return (job, data, nil)
    }
    if let empty = try? decoder.decode(Empty.self, from: data) {
        return (nil, nil, empty.next_poll_seconds)
    }
    throw WorkerClientError.decode("/poll body=\(String(data: data, encoding: .utf8) ?? "<binary>")")
}

