    static func buildArguments(
        spec: AgentSpec,
        prompt: String,
        config: AutomationPayload.ExecutionConfig?,
        mcpArgs: [String],
        timeout: TimeInterval
    ) -> [String] {
        var args: [String] = []
        var trailingPrompt: String?
        switch spec.promptDelivery {
        case let .flag(flag):
            args += [flag, prompt]
        case let .positional(subcommand):
            args += subcommand
